from solution import rule_merge_no_files

def test_valid_git_event_no_files():
    """Valid event from git with no files touched."""
    event = {'source': 'git', 'files': []}
    assert rule_merge_no_files(event, []) is True

def test_non_git_event_no_files():
    """Event from non-git source (should return False)."""
    event = {'source': 'local', 'files': []}
    assert rule_merge_no_files(event, []) is False

def test_git_event_with_files():
    """Git event with files touched (should return False)."""
    event = {'source': 'git', 'files': ['file.txt']}
    assert rule_merge_no_files(event, []) is False

def test_git_event_with_files_and_empty_skip_globs():
    """Git event with files and empty skip_globs list."""
    event = {'source': 'git', 'files': []}
    assert rule_merge_no_files(event, []) is True

def test_git_event_with_empty_files_key():
    """Git event with empty files key."""
    event = {'source': 'git'}
    assert rule_merge_no_files(event, []) is True

def test_git_event_with_multiple_files():
    """Git event with multiple files (should return False)."""
    event = {'source': 'git', 'files': ['file1.txt', 'file2.txt']}
    assert rule_merge_no_files(event, []) is False

def test_git_event_with_skip_globs_ignored():
    """Git event with no files even if skip_globs provided."""
    event = {'source': 'git', 'files': []}
    assert rule_merge_no_files(event, ['*.txt']) is True
